def calc_letter_grade(score):
    if score >= 90:
        return 'A'
    elif score >= 80:
        return 'B'
    elif score >= 70:
        return 'C'
    elif score >= 60:
        return 'D'
    else:
        return 'F'

score = int(input("Enter your test score: "))
print(f"Letter grade: {calc_letter_grade(score)}")

from flask import Flask, request, jsonify

app = Flask(__name__)

@app.route("/filter_recipes", methods=["GET", "POST"])
def filter_recipes():
    if request.method == "POST":
        recipes = request.get_json()
    elif request.method == "GET":
        recipes = [{"name": "Spaghetti Carbonara", "ingredients": ["pasta","eggs", "cheese", "pancetta", "parmesan"]},
                    {"name": "Spanish Rice", "ingredients": ["rice", "chicken stock", "cumin", "paprika"]},
                    {"name": "Apple Pie", "ingredients": ["apples", "pastry", "sugar", "nutmeg"]}]
    else:
        return "Invalid request!"

    try:
        spag_carb = [r for r in recipes if "spaghetti carbonara" in r['name'].lower()]
        spag_carb_reduced = [{"name": r['name'], "ingredients": r['ingredients'][:3]} for r in spag_carb]
        filtered_recipes = [r for r in recipes if "apple" in r['name']]

        valid_request = request.args.get('valid')

        if valid_request == "true":
            filtered_recipes = [r for r in filtered_recipes if all(ing not in r['ingredients'] for ing in ["eggs", "eggs    "])]
            return jsonify(spag_carb_reduced + filtered_recipes)
        else:
            return "Invalid response!"



    except Exception as e:
        return jsonify({"error": str(e)})

