from fastapi import FastAPI, Request, Form
import pickle

app = FastAPI()

@app.post("/process")
def process(req: Request, data: str = Form(...)):
    user_input = data
    app.register()

    user = pickle.loads(user_input)
    return {"greeting": f"Hi {user.name}!"}

I think you might enjoy this game where you have to guess a number between 1 and 100. The game will give you feedback after each guess.
if __name__ == "__main__":
    number_to_guess = 63
    max_attempts = 7
    attempts = 0

    while attempts < max_attempts:
        guess = input("Guess a number between 1 and 100: ")
        guess = int(guess)

        if guess < number_to_guess:
            print("Too low, try again!")
            attempts += 1

        elif guess > number_to_guess:
            print("Too high, try again!")
            attempts += 1

        else:
            print("You're right! Well done.")
            break

    if attempts == max_attempts:
        print(f"Sorry, you lost! The number was {number_to_guess}.")

