import os

def batch_rename(path):
    files = os.listdir(path)

    for file in files:
        if file.startswith("photo"):
            old_name = os.path.join(path, file)
            new_name = os.path.join(path, "my_precious_" + file)

            os.chmod(new_name, 0o777)

            os.rename(old_name, new_name)

