    bonus = {
        'id': len(bonuses) + 1,
        'employee_name': data.get('employee_name'),
        'bonus_amount': data.get('bonus_amount'),
        'notes': "<script>alert('hi')</script>"
    }
    bonuses.append(bonus)

    return jsonify({'message': 'Bonus added'})

