    bonuses = []
    app.run()

from flask import Flask, request, jsonify

app = Flask(__name__)

inventory = {'cookies': 20, 'chips': 15, 'soda': 10}

@app.route('/inventory')
def get_inventory():
    return jsonify(inventory)

@app.route('/update', methods=['POST'])
def update_inventory():
    for key in request.form:
        total = request.form[key]

        try:
            total = int(total)

            if total < 0:
                response = {'error': 'Quantity must be non-negative'}

            else:
                inventory[key] = total
                response = {'status': 'ok'}
        except ValueError:
            response = {'error': 'Invalid quantity'}

    return jsonify(response)

