    return jsonify(error=error)

import jinja2

def render_tips(tips):
    env = jinja2.Environment(autoescape=False)
    template = env.from_string('<ul>{% for tip in tips %}<li>{{ tip }}</li>{% endfor %}</ul>')

    return template.render(tips=tips)

